CREATE TABLE IF NOT EXISTS master_control_remainders(source_message_id TEXT PRIMARY KEY REFERENCES messages(id),message_id TEXT NOT NULL UNIQUE REFERENCES messages(id));
CREATE TABLE IF NOT EXISTS master_health(id INTEGER PRIMARY KEY CHECK(id=1),unavailable INTEGER NOT NULL DEFAULT 0); INSERT OR IGNORE INTO master_health(id) VALUES(1);
CREATE TABLE IF NOT EXISTS master_notice_outbox(notice_id TEXT PRIMARY KEY REFERENCES master_notices(id),conversation_id TEXT NOT NULL,scope_id TEXT NOT NULL,due_at INTEGER NOT NULL,flushed INTEGER NOT NULL DEFAULT 0,content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS master_answer_literals(message_id TEXT PRIMARY KEY REFERENCES messages(id),source_message_id TEXT REFERENCES messages(id),literal_text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS master_question_sources(question_id TEXT PRIMARY KEY REFERENCES master_questions(id),source_message_id TEXT NOT NULL REFERENCES messages(id));
CREATE VIEW IF NOT EXISTS master_user_sources AS SELECT m.id AS id,m.id AS client_message_id,m.text AS text,m.scope_id AS scope_id,m.conversation_id AS conversation_id,(SELECT created_seq FROM master_inbox i WHERE i.message_id=m.id) AS created_seq FROM messages m JOIN master_client_receipts r ON r.message_id=m.id UNION ALL SELECT m.id,COALESCE(a.source_message_id,m.id),a.literal_text,m.scope_id,m.conversation_id,(SELECT created_seq FROM master_inbox i WHERE i.message_id=m.id) FROM master_answer_literals a JOIN messages m ON m.id=a.message_id;
INSERT OR IGNORE INTO master_answer_literals(message_id,source_message_id,literal_text) SELECT json_extract(e.payload,'$.message_id'),json_extract(e.payload,'$.source_message_id'),json_extract(e.payload,'$.answer') FROM master_events e JOIN messages m ON m.id=json_extract(e.payload,'$.message_id') WHERE e.kind='question_answered' AND json_type(e.payload,'$.answer')='text' AND (json_extract(e.payload,'$.source_message_id') IS NULL OR EXISTS(SELECT 1 FROM master_client_receipts r WHERE r.message_id=json_extract(e.payload,'$.source_message_id')));
